# Extra sections for posts 11 to 20
def _add(slug, secs):
    EXTRA[slug] = EXTRA.get(slug, []) + secs

_add('tour-operator-website-sri-lanka', [
 ('content', 'Content That Wins Travellers’ Trust', P(
   'Travellers read a lot before they book. Beyond tour pages, publish practical guides that show your knowledge: the best time to visit each region, how long the drive is between Kandy and Ella, what to wear at temples, how safari parks compare, and suggested routes for one, two and three weeks. Each guide answers a real question and introduces your tours naturally.',
   'Add an “About us” page with photos and stories of your drivers and guides, how long they have worked with you and the languages they speak. Travellers are choosing the people they will spend their holiday with, so personal stories matter far more than generic marketing text.')),
 ('reviews', 'Showcase Reviews From Many Sources', P(
   'Travellers check reviews on several platforms. Show highlights from TripAdvisor, Google and other review sites on your website, with links to the full profiles so visitors can verify them. Ask guests for reviews at the end of each trip, while the experience is fresh, and make it easy with direct links sent by WhatsApp or email.',
   'Photos shared by guests, with permission, are especially convincing. A gallery of real guests at real places tells a story that no stock image can.')),
 ('season', 'Plan for Seasons and Markets', P(
   'Sri Lanka has different peak seasons on each coast, and source markets book at different times. Update your website before each season with relevant tours, offers and travel advice, and publish content for each market several months before their main booking period. Seasonal pages that you update each year, rather than creating new ones, build authority over time.')),
 ('checklist', 'Tourism Website Checklist', ul([
   'Fast, mobile-friendly design with real photos.',
   'Tour pages with itineraries, inclusions, exclusions and “from” prices.',
   'WhatsApp, email and enquiry form on every tour page.',
   'Reviews, company registration and licence details.',
   'Clear payment, cancellation and refund terms.',
   'Travel guides answering common traveller questions.',
   'Google Business Profile and TripAdvisor linked to the website.'])),
])
_add('school-website-design-sri-lanka', [
 ('news', 'Keep the Website Alive With News and Events', P(
   'A school or institute website that has not changed in two years suggests an organisation that is not very active. Publish news about sports meets, prize-giving ceremonies, competition results, new courses, exam successes and community projects. Each update gives parents a reason to return, gives search engines fresh content and builds pride among students and staff.',
   'Assign one person to publish at least one update a month, with photos taken during the event. A simple content management system makes this possible without any technical skills.')),
 ('admissions', 'Make Admissions Easy to Understand', P(
   'Admission questions take up a lot of office time. Put the answers on the website: age or grade requirements, the admission process step by step, required documents, important dates, fees and payment options, and who to contact. A downloadable prospectus or application form can help, but the key information should also be on the page itself so it is quick to read on a phone.',
   'For tuition classes, explain how new students can join mid-term, whether trial classes are available and how to catch up on missed lessons.')),
 ('portal', 'Student and Parent Portals', P(
   'Larger institutes can add a secure portal where students access notes, recorded lessons and results, and parents see attendance, payments and announcements. Portals reduce paperwork and phone calls, but they need careful planning, secure logins and clear responsibility for keeping information up to date. Our guide to <a href="web-development-sri-lanka.html">web development in Sri Lanka</a> explains how custom systems like these are planned and built.')),
 ('checklist', 'Education Website Checklist', ul([
   'Clear subjects, grades or courses with fees and schedules.',
   'Teacher profiles with qualifications.',
   'Results and achievements, published with permission.',
   'Online registration and, if needed, online payments.',
   'News, events and gallery updated regularly.',
   'Google Business Profile for each campus or class location.',
   'Fast, mobile-friendly pages with WhatsApp contact.'])),
])
_add('real-estate-website-sri-lanka', [
 ('overseas', 'Selling to Sri Lankans Living Abroad', P(
   'Sri Lankans living abroad are an important group of property buyers. They often buy land or houses for family, for their return or as an investment, but they cannot easily visit. Your website can make the process much easier: detailed descriptions, many photos and videos, distances to schools, hospitals and towns, and clear explanations of the buying process and documents.',
   'Offer video calls and live virtual viewings, list prices clearly and respond quickly across time zones using WhatsApp. Buyers who feel informed and supported are far more likely to trust you with a large purchase from far away.')),
 ('content', 'Area Guides and Market Content', P(
   'Helpful content attracts buyers early in their research. Write guides about the areas you sell in: what each area is like, transport links, schools and services, typical land prices and future developments. Explain topics buyers worry about, such as checking deeds, the steps to transfer property and the costs involved.',
   'These articles bring visitors from search for months and years, show your expertise, and give you natural places to feature current listings.')),
 ('speed', 'Keep Listing Pages Fast', P(
   'Property websites are often image-heavy, which can make them slow. Compress photos, show smaller thumbnails in search results and load larger images only when a visitor opens a listing. A fast website keeps buyers browsing and helps your pages perform better in search. Our <a href="website-speed-optimisation.html">speed guide</a> explains the techniques.')),
 ('checklist', 'Property Website Checklist', ul([
   'Searchable listings with filters for type, area, price and size.',
   'Full details, photos and maps on every listing.',
   'WhatsApp and call buttons with the listing reference included.',
   'Project pages with plans, progress and payment options for developers.',
   'Area guides and buyer guides for SEO.',
   'An easy admin panel to add, update and mark listings as sold.'])),
])
_add('website-content-writing-tips', [
 ('home', 'Writing Your Home Page', P(
   'Your home page has one job: help each visitor quickly find what they came for and take the next step. Start with a clear headline about what you offer and where. Follow with a short paragraph about who you help and why you are different. Then summarise your main services, each linking to its own page, show proof such as reviews and examples of your work, and finish with a clear call to action.',
   'Resist the temptation to say everything on the home page. Its role is to point visitors in the right direction, not to answer every question.')),
 ('about', 'Writing Your About Page', P(
   'The About page is one of the most visited pages on many business websites, because people want to know who they will deal with. Tell your story briefly, introduce the people behind the business with real photos, explain your experience and values, and share facts that build confidence, such as years in business, projects completed and areas served.',
   'Keep it focused on what matters to customers. Your history is interesting when it explains why you are good at what you do.')),
 ('faq', 'Use FAQs to Answer Objections', P(
   'Every customer has questions and doubts before buying: How much does it cost? How long will it take? What if I am not happy? Do you work in my area? A frequently asked questions section answers these directly and removes reasons to hesitate. It also helps your pages appear for question-based searches and in AI search answers.',
   'Collect real questions from phone calls, WhatsApp messages and emails, and answer them honestly and specifically.')),
 ('update', 'Keep Content Fresh', P(
   'Outdated content damages trust. Review your main pages every few months, update prices and examples, add new projects and reviews, and remove old offers. Publishing helpful articles regularly, as we do on our <a href="blog.html">blog</a>, keeps your website active and gives customers more reasons to choose you.')),
])
_add('whatsapp-for-business-website', [
 ('scripts', 'Useful Quick Replies to Prepare', P(
   'Quick replies let you answer common questions in seconds with a consistent, professional message. Prepare short templates for the questions you hear most, then personalise them before sending.') + ul([
   'A greeting that thanks the customer and asks how you can help.',
   'Your price list or packages, with a link to the prices page on your website.',
   'Opening hours, address and a Google Maps link.',
   'Delivery areas, charges and timelines.',
   'Payment methods and bank details for transfers.',
   'A follow-up message for customers who asked for a quote but have not replied.',
   'A thank-you message with your Google review link after a sale.'])),
 ('catalogue', 'Set Up a WhatsApp Catalogue', P(
   'The catalogue feature in WhatsApp Business lets you list products or services with photos, prices and descriptions. Customers can browse it inside the chat and send you an item directly. Keep it in sync with your website so prices and availability match, and link back to the full product pages for customers who want more details.',
   'For businesses with many products, the website remains the main shop window, while the catalogue highlights best sellers and current offers.')),
 ('team', 'Managing WhatsApp as a Team', P(
   'When enquiries grow, one phone becomes a bottleneck. Decide who answers messages at different times, use labels to track the status of each conversation, and keep notes of important details. Larger businesses can move to the WhatsApp Business Platform through an approved provider, which allows several team members, automated replies and integration with other systems.',
   'Whatever the size of your team, the goal is the same: every customer who taps the WhatsApp button on your website should get a fast, helpful reply.')),
])
_add('website-security-guide', [
 ('staff', 'Train Your Team', P(
   'Many security problems start with people rather than technology. Staff may reuse passwords, click on fake emails that look like they come from your bank or hosting company, or install unknown plugins. Spend a few minutes explaining the basics: never share passwords, check the sender carefully before clicking links, and ask before installing anything on the website.',
   'Phishing emails often warn that your domain or hosting is about to expire and ask you to pay through a link. Always log in to your provider directly instead of clicking links in unexpected emails.')),
 ('plan', 'Create a Simple Security Plan', P(
   'Write down the essentials on one page: where your website and domain are hosted, who has admin access, where backups are stored, who to call if something goes wrong and how to restore the site. Review it twice a year. When a problem happens, this page saves hours of confusion and helps you act quickly.')),
 ('checklist', 'Website Security Checklist', ul([
   'HTTPS active on every page, with automatic SSL renewal.',
   'Content management system, themes and plugins up to date.',
   'Unused plugins, themes, users and old files removed.',
   'Strong unique passwords and two-factor authentication.',
   'Automatic backups stored off the server and tested.',
   'Spam protection on forms and safe handling of uploads.',
   'Uptime and security monitoring with alerts.',
   'A written plan for what to do if the site is hacked.'])),
])
_add('ux-design-tips', [
 ('mistakes', 'Common UX Mistakes on Business Websites', ul([
   'Sliders that rotate before visitors can read them.',
   'Contact details hidden only on the contact page.',
   'Menus with vague labels or too many options.',
   'Pop-ups that cover the page on mobile as soon as it opens.',
   'Light grey text on white backgrounds that is hard to read.',
   'Forms that clear all fields after one small error.',
   'Buttons that look like plain text, or text that looks like buttons.'])),
 ('journeys', 'Map Your Customer Journeys', P(
   'Think about the most common reasons people visit your website: to check prices, to see your work, to find your location, to book or to buy. For each one, count the taps it takes to reach the goal from the home page and from Google. If any journey takes more than three or four steps, simplify it with clearer links, better headings or a more prominent button.',
   'This simple exercise often reveals easy wins, such as adding prices to service pages, a portfolio link in the menu or a WhatsApp button on product pages.')),
 ('measure', 'Measure UX With Real Numbers', P(
   'Good UX shows up in your analytics. Watch how many visitors leave without interacting, how far they scroll, which buttons they click and how many complete enquiries or purchases. Compare these numbers before and after changes. Over time, small improvements in each step add up to a noticeably better-performing website.')),
])
_add('how-to-get-website-on-google', [
 ('mistakes', 'Common Reasons Pages Are Not Indexed', table(
   ['Status in Search Console', 'What it usually means'], [
    ['Discovered, currently not indexed', 'Google knows the page but has not crawled it yet; often improves with time and internal links'],
    ['Crawled, currently not indexed', 'Google read the page but did not see enough value; improve content quality'],
    ['Excluded by noindex tag', 'A noindex tag tells Google not to index the page'],
    ['Duplicate without user-selected canonical', 'The page is too similar to another page'],
    ['Page with redirect', 'The address redirects elsewhere; usually fine'],
    ['Not found (404)', 'The page no longer exists; redirect it if it had value']])),
 ('internal', 'Use Internal Links', P(
   'Internal links help Google discover new pages and understand which pages matter most. Link from your home page to your main service pages, from service pages to related articles, and from articles back to the relevant services. Use descriptive link text such as “website maintenance plans” rather than “click here”.',
   'New pages that nothing links to are harder for Google to find and are often treated as less important.')),
 ('monitor', 'Monitor and Improve Every Month', P(
   'Getting indexed is only the beginning. Each month, check the Performance report in Search Console to see which searches bring impressions and clicks, which pages perform best and where you appear on page two. Improving pages that already rank in positions 8 to 20 is often the fastest way to gain more visitors.',
   'Combine this with Google Analytics to see which visitors become enquiries, and focus your efforts on the pages and searches that bring real customers.')),
])
_add('generative-engine-optimisation-guide', [
 ('example', 'Example: How a Local Business Applies GEO', P(
   'Imagine a solar installation company in Kurunegala. Its website explains each service on its own page, lists typical system sizes and price ranges, shows completed projects with locations, and answers common questions such as how long installation takes and how net metering works. The About page states the company name, address, years in business and the qualified engineers who lead it.',
   'The business has a complete Google Business Profile with genuine reviews, is listed on reputable directories with the same details, and has been featured in a local news article. When someone asks an AI assistant about solar installers in the area, there is consistent, specific evidence across the web describing this company. That is GEO in practice.')),
 ('avoid', 'What to Avoid', ul([
   'Writing vague marketing text with no specific facts.',
   'Publishing large amounts of generic AI-generated content with no real expertise.',
   'Inconsistent business names, addresses or phone numbers across websites.',
   'Fake reviews or paid mentions disguised as independent content.',
   'Blocking all crawlers without considering the impact on AI search visibility.'])),
 ('start', 'Where to Start This Week', ol([
   'Write a clear facts section on your About page.',
   'Add or improve FAQs on your main service pages.',
   'Check your Google Business Profile and directory listings for consistency.',
   'Ask three happy customers for detailed reviews.',
   'Ask an AI assistant about your industry and area, and note who it recommends and why.'])),
])
_add('web-design-trends-2026', [
 ('avoid', 'Trends to Approach With Care', P(
   'Not every popular design idea suits a business website. Full-screen video backgrounds, complex 3D scenes, scroll-hijacking effects and hidden navigation menus can look impressive in a portfolio, but they often slow pages down and make websites harder to use, especially on mid-range phones and mobile data.',
   'Before adopting a trend, ask three questions: does it help visitors understand our offer, does it keep the site fast on a phone, and does it make it easier to contact us or buy? If the answer to any of them is no, leave it out.')),
 ('basics', 'The Basics Never Go Out of Style', P(
   'Behind every trend, the fundamentals stay the same. Customers want to understand what you offer, trust that you are reliable and contact you easily. A clear message, real photos, honest prices, fast pages and simple contact options will outperform the most fashionable design that lacks them.',
   'Our guides on <a href="ux-design-tips.html">UX design tips</a> and <a href="website-content-writing-tips.html">writing website content</a> focus on these timeless basics.')),
 ('sl', 'What This Means for Sri Lankan Businesses', P(
   'For most businesses in Sri Lanka, the most important trends are practical ones: mobile-first design for phone-heavy audiences, fast pages on mobile data, WhatsApp integration, clear prices, content in the languages customers use, and preparing for AI search. These bring more customers than visual effects alone.',
   'If your website was built several years ago, now is a good time to review it against these points. Our article on <a href="website-redesign-signs.html">signs your website needs a redesign</a> will help you decide.')),
])
